      REAL FUNCTION LIMIT(  TYPE,  N,  K)CC     IMPOSES LIMITS ON VARIED QUANTITIESCC     NO DESCRIPTIONCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM39B.CIN'CC     LOCAL VARIABLESC      INTEGER  K, N, NP, TYPE      REAL  AGEN(4), ALEN(4), ALIMC      DATA  AGEN/-1.E10,  1., 1.E10,  1./      DATA  ALEN/0.,      1., 0.,     0./CC---------------------------------------------------------------      NP = N      ALIM = AGEN(K)      IF (TYPE .EQ. 1 .AND. .NOT. (ACCEL .OR. LTWISS)) GO TO 10      IF (TYPE .EQ. 2) GO TO 20      IF (TYPE .EQ. 3) GO TO 30      IF (TYPE .EQ. 4) GO TO 40      IF (TYPE .EQ. 5) GO TO 50      IF (TYPE .EQ. 11) GO TO 110      IF (TYPE .EQ. 12) GO TO 120      IF (TYPE .EQ. 18) GO TO 180      IF (TYPE .EQ. 19) GO TO 190      IF (TYPE .EQ. 20) GO TO 200      IF (TYPE .EQ. 25) GO TO 250      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 280      IF (TYPE .EQ. 34) GO TO 340      IF (TYPE .EQ. 35 .OR. TYPE .EQ. 36) GO TO 350      GO TO 500C   10 ALIM = ALIM1(K)      GO TO 500C   20 ALIM = ALIM2(K)      IF (K .EQ. 1 .OR. K .EQ. 3) ALIM = ALIM/UNITI(7)      GO TO 500C   30 ALIM = ALIM3(K)      IF (K .EQ. 1 .OR. K .EQ. 3) ALIM = ALIM/UNITI(8)      GO TO 500C   40 IF (NP .GT. 6) GO TO 500      ALIM = ALIM4(K,NP)      IF (K .EQ. 1 .OR. K .EQ. 3) THEN        IF (NP .EQ. 1) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 2) ALIM = ALIM/UNITI(9)        IF (NP .EQ. 3) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 4) ALIM = ALIM/UNITI(7)        IF (NP .EQ. 6) ALIM = ALIM*UNITI(8)**2      ENDIF      GO TO 500C   50 IF (NP .GT. 5) GO TO 500      ALIM = ALIM5(K,NP)      IF (K .EQ. 1 .OR. K .EQ. 3) THEN        IF (NP .EQ. 1) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 2) ALIM = ALIM/UNITI(9)        IF (NP .EQ. 3) ALIM = ALIM/UNITI(1)        IF (NP .EQ. 4) ALIM = ALIM*UNITI(1)/UNITI(9)        IF (NP .EQ. 5) ALIM = ALIM*UNITI(8)**2      ENDIF      GO TO 500C  110 IF (NP .EQ. 1) ALIM = ALEN(K)/UNITI(8)      GO TO 500C  120 ALIM = ALIM12(K,NP)      GO TO 500C  180 IF (NP .GT. 4) GO TO 500      ALIM = ALIM18(K,NP)      IF (K .EQ. 1 .OR. K .EQ. 3) THEN        IF (NP .EQ. 1) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 2) ALIM = ALIM/UNITI(9)        IF (NP .EQ. 3) ALIM = ALIM/UNITI(1)        IF (NP .EQ. 4) ALIM = ALIM*UNITI(8)**3      ENDIF      GO TO 500C  190 IF (NP .GT. 3) GO TO 500      ALIM = ALIM19(K,NP)      IF (K .EQ. 1 .OR. K .EQ. 3) THEN        IF (NP .EQ. 1) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 2) ALIM = ALIM/UNITI(9)        IF (NP .EQ. 3) ALIM = ALIM/UNITI(12)      ENDIF      GO TO 500C  200 ALIM = ALIM20(K)/UNITI(13)      GO TO 500C  250 IF (NP .GT. 4) GO TO 500      ALIM = ALIM25(K,NP)      IF (K .EQ. 1 .OR. K .EQ. 3) THEN        IF (NP .EQ. 1) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 2) ALIM = ALIM/UNITI(9)        IF (NP .EQ. 3) ALIM = ALIM/UNITI(1)        IF (NP .EQ. 4) ALIM = ALIM*UNITI(8)**4      ENDIF      GO TO 500C  280 IF (NP .GT. 13) GO TO 500      ALIM = ALIM28(K,NP)      IF (K .EQ. 1 .OR. K .EQ. 3) THEN        IF (NP .EQ. 1) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 2) ALIM = ALIM/UNITI(9)        IF (NP .EQ. 3) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 4) ALIM = ALIM/UNITI(7)        IF (NP .EQ. 12 .OR. NP .EQ. 13) ALIM = ALIM/UNITI(7)      ENDIF      GO TO 500C  340 IF (NP .GT. 5) GO TO 500      ALIM = ALIM34(K,NP)      IF (K .EQ. 1 .OR. K .EQ. 3) THEN        IF (NP .EQ. 1) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 2) ALIM = ALIM/UNITI(9)        IF (NP .EQ. 3) ALIM = ALIM/UNITI(1)        IF (NP .EQ. 4) ALIM = ALIM*UNITI(1)/UNITI(9)        IF (NP .EQ. 5) ALIM = ALIM*UNITI(8)**2      ENDIF      GO TO 500C  350 IF (NP .GT. 4) GO TO 500      ALIM = ALIM35(K,NP)      IF (K .EQ. 1 .OR. K .EQ. 3) THEN        IF (NP .EQ. 1) ALIM = ALIM/UNITI(8)        IF (NP .EQ. 2) ALIM = ALIM/UNITI(9)        IF (NP .EQ. 3) ALIM = ALIM/UNITI(7)        IF (NP .EQ. 4) ALIM = ALIM/UNITI(7)      ENDIF      GO TO 500C  500 LIMIT = ALIM      RETURN      END